544	  [[nodiscard]] const std::vector<MemRefPtr>& GetMemRefs() const { return memrefs_; }
545	  [[nodiscard]] const std::map<const ir::Var*, std::shared_ptr<const TileType>>& GetMemRefTileTypes() const {
546	    return memref_tile_types_;
547	  }
548	
549	  /// Returns true when the visited body invokes prefetch.make_context. Drives
550	  /// PTOCodegen's decision to append the hidden runtime-owned SDMA workspace
551	  /// pointer to the emitted func.func signature.
552	  [[nodiscard]] bool UsesSdmaWorkspace() const { return uses_sdma_workspace_; }
553	
554	  /// Returns true when the visited body registers deferred task completion.
555	  /// Drives the hidden raw dispatch-args pointer shared with the kernel wrapper.
556	  [[nodiscard]] bool UsesDeferredCompletion() const { return uses_deferred_completion_; }
557	
558	  /// Returns true when the visited body invokes tile.get_block_idx or
559	  /// tile.get_block_num. Drives PTOCodegen's decision to append two synthetic
560	  /// i32 params to the emitted func.func signature; the kernel wrapper
561	  /// resolves those values from intrinsic.h::get_block_idx(args) /
562	  /// get_block_num(args) at dispatch time.
563	  [[nodiscard]] bool UsesSpmdBlockOps() const { return uses_spmd_block_ops_; }
564	
565	  /// Returns true when the visited body invokes tile.get_subblock_idx. Drives
566	  /// PTOCodegen's decision to append a synthetic i32 param to the func.func
567	  /// signature; the kernel wrapper resolves it from
568	  /// intrinsic.h::get_sub_block_id(args) at dispatch time, rather than reading
569	  /// the ccec get_subblockid() register.
570	  [[nodiscard]] bool UsesSubblockOp() const { return uses_subblock_op_; }
571	
572	  [[nodiscard]] const std::set<const ir::Var*>& GetFFTSWorkspaceVars() const { return ffts_workspace_vars_; }
573	
574	  void VisitExpr_(const VarPtr& op) override {
575	    if (iter_arg_ids_.count(op->UniqueId())) return;
576	    if (auto tile_type = ir::GetTileTypeWithMemRef(op->GetType())) {
577	      AddMemRefIfUnique(ir::GetDefinedMemRef(tile_type), tile_type);
578	    }
579	  }
580	
581	  void VisitExpr_(const ir::IterArgPtr& op) override {
582	    iter_arg_ids_.insert(op->UniqueId());
583	    ir::IRVisitor::VisitExpr_(op);
584	  }
585	
586	  void VisitExpr_(const ir::CallPtr& op) override {
587	    if (op->op_) {
588	      if (!uses_sdma_workspace_ && ir::IsOp(op, "prefetch.make_context")) {
589	        uses_sdma_workspace_ = true;
590	      }
591	      if (!uses_deferred_completion_ && ir::IsOp(op, "pld.system.defer_wait")) {
592	        uses_deferred_completion_ = true;
593	      }
594	      if (!uses_spmd_block_ops_ &&
595	          (ir::IsOp(op, "tile.get_block_idx") || ir::IsOp(op, "tile.get_block_num"))) {
596	        uses_spmd_block_ops_ = true;
597	      }
598	      if (!uses_subblock_op_ && ir::IsOp(op, "tile.get_subblock_idx")) {
599	        uses_subblock_op_ = true;
600	      }
601	      if (ir::IsOp(op, "system.set_ffts") && op->args_.size() == 1) {
602	        if (auto workspace = As<ir::Var>(op->args_[0])) {
603	          ffts_workspace_vars_.insert(workspace.get());
604	        }
605	      }
606	    }
607	    ir::IRVisitor::VisitExpr_(op);
608	  }
609	
610	 private:
611	  std::vector<MemRefPtr> memrefs_;
612	  std::set<const ir::Var*> seen_bases_;
613	  std::map<const ir::Var*, std::shared_ptr<const TileType>> memref_tile_types_;
614	  std::set<uint64_t> iter_arg_ids_;
615	  bool uses_sdma_workspace_ = false;
616	  bool uses_deferred_completion_ = false;
617	  bool uses_spmd_block_ops_ = false;
618	  bool uses_subblock_op_ = false;
619	  std::set<const ir::Var*> ffts_workspace_vars_;
620	
621	  void AddMemRefIfUnique(const MemRefPtr& memref, const std::shared_ptr<const TileType>& tile_type) {
622	    const ir::Var* base_ptr = memref->base_.get();
623	    if (seen_bases_.insert(base_ptr).second) {
624	      memrefs_.push_back(memref);
625	      memref_tile_types_[base_ptr] = tile_type;
626	    } else {
627	      // Merge TileView properties when multiple tiles share the same allocation:
628	      // - Keep valid_shape from the original tile (e.g., from load)
629	      // - Take pad from the new tile if it has a non-null pad (e.g., from fillpad)
630	      // This ensures fillpad's pad_value is used while preserving the original valid_shape
631	      auto existing = memref_tile_types_[base_ptr];
632	      if (const auto& tile_view = tile_type->tile_view_;
633	          tile_view.has_value() && tile_view->pad != ir::PadValue::null) {
634	        // Merge: keep valid_shape from existing, take pad from new tile
635	        ir::TileView merged_view;
636	        if (const auto& existing_view = existing->tile_view_) {
637	          merged_view = *existing_view;
638	        }
639	        merged_view.pad = tile_view->pad;
640	        auto merged_tile_type = std::make_shared<TileType>(
641	            existing->shape_, existing->dtype_, existing->memref_, merged_view, existing->memory_space_);
642	        memref_tile_types_[base_ptr] = merged_tile_type;
643	      }
644	    }
645	  }
