65	static bool IsSameDimExpr(const ExprPtr& lhs, const ExprPtr& rhs) {
66	  if (lhs == rhs) {
67	    return true;
68	  }
69	  auto lhs_const = As<ir::ConstInt>(lhs);
70	  auto rhs_const = As<ir::ConstInt>(rhs);
71	  return lhs_const && rhs_const && lhs_const->value_ == rhs_const->value_;
72	}
