74	static std::shared_ptr<const ir::TileType> GetTpushTileType(const ExprPtr& tile_expr) {
75	  if (auto tile_type = ir::GetTileTypeWithMemRef(tile_expr->GetType())) {
76	    return tile_type;
77	  }
78	  return As<ir::TileType>(tile_expr->GetType());
79	}
