81	static bool EmitTpushTransportValidShape(const char* target, const CallPtr& op, codegen::PTOCodegen& codegen,
82	                                         const std::string& tile_buf, const std::string& tile_type,
83	                                         int split) {
84	  // split == 0 normally means no cross-core split. Two physical FIFO cases
85	  // still require a box-normalized transport: partial Acc->Vec payloads and
86	  // the 910B no-split dual-AIV dispatch path. The latter
87	  // (function attr `dual_aiv_dispatch`) runs the producer on TWO AIV subblocks
88	  // that share one FIFO slot while the single cube consumer pops the FULL
89	  // slot. If the producer narrowed its valid_shape (e.g. set_validshape on a
90	  // partial attention block), the un-narrowed rows/cols of the slot stay stale
91	  // and feed garbage into the consumer's matmul. So for that mode we must
92	  // still transport the full box, exactly as for split==1/2 — this extends
93	  // PR #1454's fix to the split==0 dual-dispatch case.
94	  auto source_tile_type = GetTpushTileType(op->args_[0]);
95	  if (!source_tile_type || source_tile_type->shape_.size() < 2) {
96	    return false;
97	  }
98	  const bool dual_aiv_no_split = (split == 0) && codegen.IsDualAivDispatchFunction();
99	  const bool acc_to_vec_no_split = (split == 0) && std::string_view(target) == "aiv" &&
100	                                   source_tile_type->GetMemorySpace() == ir::MemorySpace::Acc;
101	  if ((split == 0 && !dual_aiv_no_split && !acc_to_vec_no_split) || tile_buf.empty() || tile_type.empty()) {
102	    return false;
103	  }
104	
105	  const auto tile_view = ir::tile_view_semantics::GetEffectiveTileView(*source_tile_type);
106	  if (tile_view.valid_shape.size() < 2) {
107	    return false;
108	  }
109	
110	  // The transport must carry the full box for both subblocks to receive
111	  // complete data: each subblock reads its half of the slot regardless of the
112	  // user-declared valid_shape. Narrowing valid_shape on the producer side
113	  // before tpush would leave the non-split axis under-written and (on LR
114	  // splits in particular) make even subblock 0 see zeros for the cells the
115	  // producer skipped. Localization back to the user's logical valid happens
116	  // on the consumer side via LocalizeValidDimForSplit.
117	  const auto& shape = source_tile_type->shape_;
118	  const auto& valid_shape = tile_view.valid_shape;
119	  ExprPtr transport_row = shape[0];
120	  ExprPtr transport_col = shape[1];
121	
122	  // A no-split Acc->Vec FIFO slot is laid out using the source's physical box,
123	  // so a partially written COLUMN range leaves stale bytes *inside* the valid
124	  // rows -- those columns must be transported at the full box width. An empty
125	  // tile remains an empty protocol operation and must not be widened at all.
126	  //
127	  // The ROW extent is the opposite: it must stay exactly as the producer wrote
128	  // it. Every L0C reader derives its source pitch from validRow --
129	  // `ceil(validRow/16)*16` for a compact tile, `TileData::Rows` otherwise
130	  // (pto-isa `tstore_common.hpp`, `TStoreAccNz2nd`) -- and `mad` laid the
131	  // result out at the pitch implied by the L0A operand's *valid* rows
132	  // (`TMatmul.hpp`: `uint16_t m = aMatrix.GetValidRow()`). Widening the rows
133	  // here re-derives that pitch from the physical box, so TPUSH walks L0C at a
134	  // stride `mad` never wrote at: with a 64-row box valid to 16 the push picks
135	  // up N-fractal 4j for every fractal j, silently corrupting the valid rows
136	  // (issue #2510). Rows past validRow stay stale in the slot, which is exactly
137	  // what a narrowed valid_shape already promises about its invalid region --
138	  // and the transport moves validRow rows instead of the whole box.
139	  if (acc_to_vec_no_split) {
140	    for (const auto& valid_dim : valid_shape) {
141	      if (auto dim_const = As<ir::ConstInt>(valid_dim); dim_const && dim_const->value_ == 0) {
142	        return false;
143	      }
144	    }
145	    transport_row = valid_shape[0];
146	  }
147	
148	  // For the 910B no-split dual-AIV path there is NO genuine cross-core row
149	  // split: subblock 0 runs the full computation while subblock 1 is a
150	  // pipe-balancing replay whose tile carries valid_shape (0, 0). So here we
151	  // widen the COLUMNS only -- carrying the producer's fillpad'd cols >=
152	  // valid_col, which fixes the stale-col feed into the consumer matmul --
153	  // while PRESERVING the producer's row valid_shape. Widening the rows to the
154	  // full box would push subblock-1's garbage rows into the shared FIFO slot
155	  // and race/overwrite subblock-0's real data. Genuine split==1/2 paths keep
156	  // widening both axes because the row split is real there.
157	  if (dual_aiv_no_split) {
158	    transport_row = valid_shape[0];
159	    // A statically-zero-row producer IS the subblock-1 pipe-balancing replay:
160	    // it moves no data regardless of the column box, so a col-widening
161	    // transport is pure overhead AND (on 910B) perturbs the shared-slot
162	    // dual-AIV merge -- emitting it regressed the cross_core_v2c_nosplit
163	    // golden. Only the real subblock-0 push (non-zero rows, possibly narrowed
164	    // by set_validshape) needs the full-column transport.
165	    if (auto row_const = As<ir::ConstInt>(transport_row); row_const && row_const->value_ == 0) {
166	      return false;
167	    }
168	  }
169	
170	  // A genuine row split needs the full box in the slot -- lane 1 reads the band
171	  // starting at the box half, which only exists if the producer wrote it -- but
172	  // writing it means reading L0C at the physical pitch, which is not the pitch
173	  // `mad` used for a row-narrowed operand. The two requirements are mutually
174	  // exclusive, so the shape is refused here instead of being lowered into
175	  // silently skewed data (measured: a 64-row box valid to 16 across
176	  // `pl.split(UP_DOWN)` returns 1808 of 8192 elements wrong). Gated on the
177	  // pitches actually differing, so a single-fractal-block accumulator -- where
178	  // `ceil(validRow/16)*16 == Rows` -- keeps crossing as before.
179	  CHECK_SPAN(!(split != 0 && tile_view.compact == ir::CompactMode::normal) ||
180	                 ir::AccPitchesCoincide(valid_shape[0], shape[0]),
181	             op->span_)
182	      << "a row-narrowed matmul accumulator cannot cross a split Cube-to-Vector boundary: mad wrote "
183	      << "L0C at the pitch implied by the matmul's valid rows, while a split transport must carry "
184	      << "the full physical box so both vector lanes receive their band. Either drop the row "
185	      << "narrowing on the matmul's left operand (narrow the result with pl.set_validshape "
186	      << "instead), or route the accumulator through GM and dequantize it in a second scope.";
187	
188	  if (IsSameDimExpr(transport_row, valid_shape[0]) && IsSameDimExpr(transport_col, valid_shape[1])) {
189	    return false;
190	  }
191	
192	  std::string row = EmitIndexOperand(codegen, transport_row, "tpush transport valid_row");
193	  std::string col = EmitIndexOperand(codegen, transport_col, "tpush transport valid_col");
194	  codegen.Emit("pto.set_validshape " + tile_buf + ", " + row + ", " + col + " : " + tile_type);
195	  return true;
196	}
197	
198	static void EmitLogicalTpushValidShapeRestore(const CallPtr& op, codegen::PTOCodegen& codegen,
199	                                              const std::string& tile_buf, const std::string& tile_type) {
200	  auto source_tile_type = GetTpushTileType(op->args_[0]);
201	  INTERNAL_CHECK(source_tile_type) << "Internal error: tpush validShape restore requires a TileType source";
202	  const auto tile_view = ir::tile_view_semantics::GetEffectiveTileView(*source_tile_type);
203	  INTERNAL_CHECK(tile_view.valid_shape.size() >= 2)
204	      << "Internal error: tpush validShape restore requires rank-2 validShape";
205	  const auto& valid_shape = tile_view.valid_shape;
206	  std::string row = EmitIndexOperand(codegen, valid_shape[0], "tpush logical valid_row");
207	  std::string col = EmitIndexOperand(codegen, valid_shape[1], "tpush logical valid_col");
208	  codegen.Emit("pto.set_validshape " + tile_buf + ", " + row + ", " + col + " : " + tile_type);
209	}
