247	// tile.tpush_to_{aic,aiv}: Push a tile across cores (Cube<->Vector). `target`
248	// is "aic" or "aiv" and selects both the emitted pto op name and diagnostics.
249	static std::string MakeTpushCodegenPTO(const char* target, const CallPtr& op,
250	                                       codegen::CodegenBase& codegen_base) {
251	  auto& codegen = AsPto(codegen_base);
252	  const std::string op_name = std::string("tpush_to_") + target;
253	
