331	//   1. %dst_view = pto.subview %dst[row, col] sizes [R, C] valid [vr, vc] : ... -> ...
332	//   2. %src_pview = pto.partition_view %src_view, offsets = [...], sizes = [vr, vc] : ... -> ...
333	//   3. pto.tload ins(%src_pview) outs(%dst_view)
334	// Filling an L1 (Mat) tile is only valid via GM->Mat tload (MAT->MAT tmov is
335	// unsupported on a2a3), so the row is written straight into the accumulator
336	// sub-region. DPS: %dst is the in-place result target. ``transpose`` swaps the
337	// destination subview dims (GM row [r, c] -> L1 column [c, r]) for the matmul
338	// B-operand layout.
339	//
340	// The optional 6th operand ``valid_shape`` carries the *runtime* transfer extent
341	// [vr, vc]; without it the transfer covers the whole [R, C] window and the emitted
342	// text is byte-identical to the pre-valid_shape lowering. The split matters
343	// because ptoas types pto.subview's `sizes` as a static I64ArrayAttr while
344	// `valid_row`/`valid_col` are Optional<Index> SSA operands (PTOOps.td SubViewOp) —
345	// so only the valid side, and the GM partition_view sizes, can be dynamic.
346	static std::string MakeGatherRowCodegenPTO(const CallPtr& op, codegen::CodegenBase& codegen_base) {
347	  auto& codegen = AsPto(codegen_base);
348	  INTERNAL_CHECK_SPAN(op->args_.size() == 5 || op->args_.size() == 6, op->span_)
349	      << "tile.gather_row requires 5-6 arguments "
350	         "(dst, src, dst_offset, src_offset, shapes[, valid_shape]), got "
351	      << op->args_.size();
352	
353	  auto dst_tile_type = ir::As<ir::TileType>(op->args_[0]->GetType());
354	  INTERNAL_CHECK_SPAN(dst_tile_type, op->span_) << "tile.gather_row dst must be a TileType";
355	  auto src = ir::AsVarLike(op->args_[1]);
356	  INTERNAL_CHECK_SPAN(src, op->span_) << "tile.gather_row src must be a Var or IterArg";
357	  auto src_tensor_type = ir::AsTensorTypeLike(src->GetType());
358	  INTERNAL_CHECK_SPAN(src_tensor_type, op->span_) << "tile.gather_row src must have TensorType";
359	
360	  auto dst_off = ir::As<ir::MakeTuple>(op->args_[2]);
361	  auto src_off = ir::As<ir::MakeTuple>(op->args_[3]);
362	  auto shapes = ir::As<ir::MakeTuple>(op->args_[4]);
363	  INTERNAL_CHECK_SPAN(dst_off && src_off && shapes, op->span_)
364	      << "tile.gather_row offsets and shapes must be literal tuples";
365	  INTERNAL_CHECK_SPAN(
366	      dst_off->elements_.size() >= 2 && src_off->elements_.size() >= 2 && shapes->elements_.size() >= 2,
367	      op->span_)
368	      << "tile.gather_row offsets and shapes must have at least 2 elements";
369	
370	  // Optional valid_shape: the runtime transfer extent inside the static window.
371	  // Absent => the whole window, which reproduces the original 5-arg lowering.
372	  auto valid = shapes;
373	  if (op->args_.size() == 6) {
374	    valid = ir::As<ir::MakeTuple>(op->args_[5]);
375	    INTERNAL_CHECK_SPAN(valid && valid->elements_.size() >= 2, op->span_)
376	        << "tile.gather_row valid_shape must be a literal tuple with at least 2 elements";
377	  }
378	
379	  bool transpose = false;
380	  for (const auto& [k, v] : op->kwargs_) {
381	    if (k == "transpose") transpose = AnyCast<bool>(v, "transpose");
382	  }
383	
384	  // Constant `shapes`, and static valid under transpose, are op preconditions the
385	  // deducer already rejected with a user-facing message (DeduceTileGatherRowType).
386	  // Reaching codegen without them means a pass built the call, i.e. a compiler bug.
387	  auto r_const = ir::As<ir::ConstInt>(shapes->elements_[0]);
388	  auto c_const = ir::As<ir::ConstInt>(shapes->elements_[1]);
389	  INTERNAL_CHECK_SPAN(r_const && c_const, op->span_)
390	      << "Internal error: tile.gather_row shapes must be compile-time constants for pto.subview sizes";
391	  // Destination subview shape: transpose maps a GM row [r, c] to an L1 column [c, r].
392	  const int64_t sv_rows = transpose ? c_const->value_ : r_const->value_;
393	  const int64_t sv_cols = transpose ? r_const->value_ : c_const->value_;
394	
395	  // Transfer extent in *GM partition* order. transpose presents the GM row [r, c]
396	  // as a DN column, so the source order is swapped there — and that swap makes
397	  // the first two entries the destination subview's [valid_row, valid_col] in
398	  // both cases (same rule as sv_rows/sv_cols above).
399	  const std::vector<ExprPtr> xfer_elems =
400	      transpose ? std::vector<ExprPtr>{valid->elements_[1], valid->elements_[0]} : valid->elements_;
401	  auto vr_const = ir::As<ir::ConstInt>(xfer_elems[0]);
402	  auto vc_const = ir::As<ir::ConstInt>(xfer_elems[1]);
403	  INTERNAL_CHECK_SPAN(!transpose || (vr_const && vc_const), op->span_)
404	      << "Internal error: tile.gather_row transpose=True requires a static valid_shape";
405	
406	  std::string dst = codegen.GetCurrentResultTarget();
407	  std::string dst_type = codegen.GetCurrentResultTileBufTypeString();
408	  std::string row_off = codegen.GetExprAsCode(dst_off->elements_[0]);
409	  std::string col_off = codegen.GetExprAsCode(dst_off->elements_[1]);
410	
411	  // Build the destination subview type from the accumulator's tile type, with the
412	  // per-row shape/valid.
413	  const auto dst_space = dst_tile_type->memory_space_.value_or(ir::MemorySpace::Mat);
414	  auto view_info = codegen::ExtractTileTypeInfo(*dst_tile_type, codegen.GetTypeString(dst_tile_type->dtype_));
415	
416	  // In a boxed (NZ/fractal) layout — i.e. an L1/Mat matmul operand — the inner
417	  // box has a fixed granularity, and pto.subview requires the *physical* size to
418	  // be a whole number of boxes per dim (ptoas: "boxed layout subview sizes must
419	  // be multiples of inner shape"). A per-row gather writes a single row, so we
420	  // carve a box-aligned physical sub-region (size = phys_rows x phys_cols) but
421	  // mark only the real extent valid; the tload then fills just that row. ND tiles
422	  // (Vec, slayout=none_box) have no inner box and use the exact per-row size.
423	  // Alignment is computed from the *static* window (sv_rows/sv_cols), never from
424	  // valid_shape, so a dynamic transfer extent leaves the physical carve-out — and
425	  // hence this box-multiple invariant — untouched.
426	  const bool boxed = view_info.slayout != ir::TileLayout::none_box;
427	  const auto box_alignment = ir::tile_view_semantics::GetBoxedTileAlignment(*dst_tile_type);
428	  INTERNAL_CHECK_SPAN(!boxed || box_alignment.has_value(), op->span_)
429	      << "Internal error: tile.gather_row destination uses an unsupported boxed layout";
430	  auto round_up = [](int64_t n, int64_t mult) { return ((n + mult - 1) / mult) * mult; };
431	  const int64_t phys_rows = boxed ? round_up(sv_rows, box_alignment->rows) : sv_rows;
432	  const int64_t phys_cols = boxed ? round_up(sv_cols, box_alignment->cols) : sv_cols;
433	
434	  view_info.rows = phys_rows;
435	  view_info.cols = phys_cols;
436	  // Per-dim static/dynamic, deliberately NOT promoted together — see the same
437	  // handling in tile.slice below for why PTOAS requires this.
438	  view_info.v_row_dynamic = vr_const == nullptr;
439	  view_info.v_col_dynamic = vc_const == nullptr;

