44	/// Join a vector of strings with ", " separator
45	static std::string JoinCommaSep(const std::vector<std::string>& items) {
46	  std::ostringstream oss;
47	  for (size_t i = 0; i < items.size(); ++i) {
48	    if (i > 0) oss << ", ";
49	    oss << items[i];
50	  }
51	  return oss.str();
52	}
