54	/// Join pairs of strings as "a sep b" with ", " between pairs
55	static std::string JoinPairs(const std::vector<std::string>& lhs, const std::string& sep,
56	                             const std::vector<std::string>& rhs) {
57	  INTERNAL_CHECK(lhs.size() == rhs.size()) << "Internal error: JoinPairs size mismatch";
58	  std::ostringstream oss;
59	  for (size_t i = 0; i < lhs.size(); ++i) {
60	    if (i > 0) oss << ", ";
61	    oss << lhs[i] << sep << rhs[i];
62	  }
63	  return oss.str();
64	}
