70	void PTOCodegen::VisitStmt_(const EvalStmtPtr& op) {
71	  INTERNAL_CHECK(op != nullptr) << "Internal error: null EvalStmt";
72	  INTERNAL_CHECK_SPAN(op->expr_ != nullptr, op->span_) << "Internal error: EvalStmt has null expression";
73	  VisitExpr(op->expr_);
74	}
75	
76	void PTOCodegen::VisitStmt_(const YieldStmtPtr& op) {
77	  INTERNAL_CHECK(op != nullptr) << "Internal error: null YieldStmt";
78	
79	  if (op->value_.empty()) {
80	    return;
81	  }
82	
83	  std::vector<std::string> yielded_values;
84	  for (const auto& expr : op->value_) {
85	    // Tensors are mutable references: a branch may yield either a freshly
86	    // stored-into tensor (bound to its tensor_view) or the unchanged input (a
87	    // param bound only to its base ptr). Normalize tensor yields to the
88	    // canonical tensor_view so consumers — notably the IfStmt in-place
89	    // return_var binding — see a consistent SSA across branches that aliases
90	    // the same concrete make_tensor_view (issue #1533). For/While loops keep
91	    // only scalar yields, so this does not affect their lowering.
92	    if (ir::AsTensorTypeLike(expr->GetType())) {
93	      if (auto tensor_var = ir::AsVarLike(expr)) {
94	        // Only normalize when a tensor_view is actually registered. Some
95	        // tensors (e.g. return-value / loop phis without a make_tensor_view)
96	        // have no view at yield time; for those fall through to the default
97	        // expr lowering rather than hard-failing in GetOrCreateTensorView.
98	        if (std::string view = TryGetTensorView(tensor_var); !view.empty()) {
99	          // Cache view → base ptr so an IfStmt rebinding its phi return_var to
100	          // this shared view can also restore the base ptr (else
101	          // GetTensorBasePtr would fall back to the view SSA). Both branches
102	          // yield the same backing, so the recorded base ptr is consistent.
103	          fs_.view_ssa_to_base_ptr[view] = GetTensorBasePtr(tensor_var);
104	          if (As<ir::DistributedTensorType>(expr->GetType())) {
105	            INTERNAL_CHECK_SPAN(!GetCommCtxSSAFor(tensor_var.get()).empty(), op->span_)
106	                << "Internal error: yielded DistributedTensor '" << tensor_var->name_hint_
107	                << "' has no CommContext binding";
108	          }
109	          yielded_values.push_back(view);
110	          continue;
111	        }
112	      }
113	    }
114	    VisitExpr(expr);
115	    yielded_values.push_back(fs_.current_expr_value);
116	    fs_.current_expr_value = "";
117	  }
118	  fs_.yield_buffer = yielded_values;
119	}
