128	// A ScopeStmt subtype (InCoreScopeStmt, SpmdScopeStmt, ...) has its own
129	// ObjectKind, so As<ScopeStmt> misses it; match the whole family by base type.
130	std::shared_ptr<const ir::ScopeStmt> AsScope(const StmtPtr& s) {
131	  return std::dynamic_pointer_cast<const ir::ScopeStmt>(s);
132	}
