134	// Find the YieldStmt terminating a branch body (last yield, recursing through the
135	// trailing SeqStmts and any scope wrappers). Used to recover the per-slot yield
136	// source so a branch-local producer can be re-pointed at the phi handle.
137	YieldStmtPtr FindBranchYield(const StmtPtr& body) {
138	  if (!body) return nullptr;
139	  if (auto y = As<ir::YieldStmt>(body)) return y;
140	  if (auto seq = As<ir::SeqStmts>(body)) {
141	    for (auto it = seq->stmts_.rbegin(); it != seq->stmts_.rend(); ++it) {
142	      if (auto y = FindBranchYield(*it)) return y;
143	    }
144	  }
145	  if (auto scope = AsScope(body)) return FindBranchYield(scope->body_);
146	  return nullptr;
147	}
