149	// True when `var` is defined lexically inside `body` — an AssignStmt result, a
150	// loop iter-arg/return-var, or a nested control-flow return-var — i.e. a
151	// branch-local value whose handle can be safely re-pointed at the phi buffer. A
152	// yield source that is NOT branch-local (a function param / outer-scope tile
153	// threaded through the branch unchanged) must not be re-bound: its handle is read
154	// elsewhere, so re-pointing it would corrupt those reads.
155	bool IsDefinedInBranch(const ir::Var* var, const StmtPtr& body) {
156	  if (!body || !var) return false;
157	  if (auto assign = As<ir::AssignStmt>(body)) {
158	    // Only a real op producer (Call value) writes a fresh buffer we may re-point.
159	    // A bare-var alias (`r = a`) or a view writes nothing at its own handle, so
160	    // re-pointing it would leave the phi buffer unwritten — the tmov fallback in
161	    // emit_branch copies those into the phi handle instead.
162	    if (assign->var_.get() != var) return false;
163	    auto call = As<ir::Call>(assign->value_);
164	    if (!call || !call->op_) return false;
165	    // A zero-copy view (inherit-input: tile.reshape, tile.slice, ...) IS the
166	    // "view" the comment above excludes. Its codegen emits nothing when the target
167	    // handle already carries the result type, so re-pointing it at the phi handle
168	    // leaves the phi buffer unwritten. `[N, 1]` col-vector carries always hit this:
169	    // their elementwise ops run on a `[1, N]` row-major view and the branch yields
170	    // the reshape back, not the op result.

