302	         "4=left-right/odd), got "
303	      << split;
304	  CHECK(!(ir::IsOddSplitCode(split) && std::string_view(target) == "aiv"))
305	      << op_name << ": pto-isa has no odd split for the Vector -> Cube direction (split = " << split
306	      << "). Only the Cube -> Vector shard splits an odd axis.";
307	
308	  std::string result_buf = codegen.GetCurrentResultTarget();
309	  INTERNAL_CHECK_SPAN(!result_buf.empty(), op->span_) << op_name << " requires assignment target (tile_buf)";
310	  std::string result_type = codegen.GetCurrentResultTileBufTypeString();
311	  auto [logical_row, logical_col] = codegen.GetCurrentResultTpopValidShapeOperands();
312	
313	  // PTO's Cube->Vector FIFO copies the physical consumer box, at EVERY split.
314	  // pto-isa builds the GM slot view from the popped tile's compile-time
315	  // rows/cols and the producer's box row pitch (a2a3 TPush.hpp
316	  // popVecTileFromGMFiFo: gmValidR/gmValidC = ConsM/ConsN, gmStrideR = ProdN),
317	  // then strides that view with the tile's RUNTIME validCol (TLoadGm2ubNd2nd:
318	  // lenBurst = validCol, but gmGap = gStride3 - gShape4). A narrowed validCol
319	  // therefore collapses the GM gap to zero and the pop reads one contiguous
320	  // run instead of one box row per burst -- silently, since the matching
321	  // PTO_ASSERT(validCol == gShape4) is compiled out in release builds. Give
322	  // TPOP the full-box extent, mirroring the producer-side widening in
323	  // EmitTpushTransportValidShape, then restore the logical result shape before
324	  // any vector consumer sees it. Keep a statically empty pop empty: the
325	  // dual-AIV no-split path uses such a replay only to balance the pipe, and a
326	  // split lane whose localized valid extent is statically 0 must likewise
327	  // move nothing.
328	  auto result_tile_type = codegen.GetCurrentResultTileType();
329	  bool statically_empty = false;
330	  bool has_static_logical_shape = false;
331	  if (result_tile_type) {
332	    const auto result_view = ir::tile_view_semantics::GetEffectiveTileView(*result_tile_type);
333	    has_static_logical_shape = result_view.valid_shape.size() >= 2;
334	    for (const auto& valid_dim : result_view.valid_shape) {
335	      auto dim_const = As<ir::ConstInt>(valid_dim);
336	      has_static_logical_shape = has_static_logical_shape && static_cast<bool>(dim_const);
337	      if (dim_const && dim_const->value_ == 0) {
